"""Run MajorTrack on the synthetic scenarios generated by main.R and score the
resulting dynamic clusters (DCs) against the ground-truth assignments.

Pipeline, for each scenario folder in data/:
  1. Read the T=100 interaction matrices and the M=10 ground-truth assignments
     (assignment m generated time steps 10*m ... 10*m+9).
  2. Symmetrise each interaction matrix (A | A^T) and detect static communities
     at every time step with Leiden (modularity, fixed seed).
  3. Run MajorTrack on the resulting time series of groupings for several
     values of the history parameter.
  4. Compare static groups and DCs with the ground truth and save results in
     <scenario>/majortrack_results/.
A summary over all scenarios is written to data/majortrack_summary.csv and
data/majortrack_summary.pdf.

Usage (from synthetic_simulations/):
  python src/run_majortrack.py                 # all scenarios
  python src/run_majortrack.py merge-split     # only scenarios whose name contains it
"""
import glob
import os
import sys
import warnings

import igraph as ig
import leidenalg
import matplotlib
import numpy as np
import pandas as pd
import rdata
from sklearn.metrics import adjusted_rand_score, normalized_mutual_info_score

matplotlib.use('Agg')
warnings.filterwarnings('ignore', category=SyntaxWarning)
from matplotlib import pyplot as plt  # noqa: E402
from majortrack import MajorTrack  # noqa: E402

HISTORIES = [1, 2, 3, 5, 10, 20, 50]
HISTORY_PLOT = 5     # history used for the membership heatmaps
STEPS_PER_MATRIX = 10
SEED = 25022025

DIR_DATA = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'data')


def read_scenario(folder):
    label = os.path.basename(os.path.normpath(folder))
    mats = rdata.read_rds(os.path.join(folder, f'matrices_interaction_{label}.RDS'))
    assign = rdata.read_rds(os.path.join(folder, f'assignments_{label}.RDS'))
    mats = [np.asarray(m) for m in mats]
    assign = [np.asarray(a).astype(int) for a in assign]
    truth = np.array([assign[t // STEPS_PER_MATRIX] for t in range(len(mats))])
    return label, mats, truth


def static_communities(mat, seed):
    adj = ((mat + mat.T) > 0).astype(int)
    g = ig.Graph.Adjacency(adj.tolist(), mode='undirected')
    part = leidenalg.find_partition(g, leidenalg.ModularityVertexPartition, seed=seed)
    return np.array(part.membership)


def run_majortrack(groupings, n, history):
    clusterings = [[set(np.flatnonzero(lab == c).tolist()) for c in np.unique(lab)]
                   for lab in groupings]
    mt = MajorTrack(clusterings=clusterings,
                    individuals=[set(range(n)) for _ in clusterings],
                    history=history)
    mt.get_group_matchup('fraction')
    mt.get_dcs()
    mt.get_community_membership()
    mt.get_individual_membership()
    dc = np.array([[mt.individual_membership[t][i] for i in range(n)]
                   for t in range(len(clusterings))])
    return dc


def label_changes(labels, valid):
    """Mean fraction of elements whose (global) label changes between consecutive
    steps, separately for steps where the ground truth is constant (any change
    is spurious) and for steps at block boundaries (where true events occur).
    Only pairs of steps that are both valid are considered."""
    within, boundary = [], []
    for t in range(1, len(labels)):
        if not (valid[t] and valid[t - 1]):
            continue
        frac = np.mean(labels[t] != labels[t - 1])
        (boundary if t % STEPS_PER_MATRIX == 0 else within).append(frac)
    return np.mean(within), np.mean(boundary)


def score(labels, truth, valid, global_labels=True):
    """Per-step NMI/ARI (NaN at non-valid steps) and global NMI over the
    (element, time) pairs of valid steps."""
    per_step_nmi = np.array([normalized_mutual_info_score(truth[t], labels[t])
                             for t in range(len(truth))])
    per_step_ari = np.array([adjusted_rand_score(truth[t], labels[t])
                             for t in range(len(truth))])
    per_step_nmi[~valid] = np.nan
    per_step_ari[~valid] = np.nan
    if not global_labels:  # labels are only meaningful within a time step: make them unique
        labels = labels + 1000 * np.arange(len(labels))[:, None]
    glob_nmi = normalized_mutual_info_score(truth[valid].ravel(), labels[valid].ravel())
    return per_step_nmi, per_step_ari, glob_nmi


def membership_heatmap(ax, labels, order, title):
    # recode labels to consecutive integers by order of first appearance
    codes = {}
    for v in labels.T[order].ravel(order='F'):
        codes.setdefault(v, len(codes))
    img = np.vectorize(codes.get)(labels[:, order].T)
    cmap = plt.get_cmap('tab20', max(len(codes), 2))
    ax.imshow(img % 20, aspect='auto', interpolation='nearest', cmap=cmap, vmin=0, vmax=19)
    for b in range(STEPS_PER_MATRIX, labels.shape[0], STEPS_PER_MATRIX):
        ax.axvline(b - 0.5, color='k', lw=0.4, ls=':')
    ax.set_title(f'{title} ({len(codes)} labels)', fontsize=9)
    ax.set_xlabel('time step')


def analyse(folder):
    label, mats, truth = read_scenario(folder)
    n, T = truth.shape[1], truth.shape[0]
    out = os.path.join(folder, 'majortrack_results')
    os.makedirs(out, exist_ok=True)

    static = np.array([static_communities(m, SEED + t) for t, m in enumerate(mats)])
    pd.DataFrame(static.T, columns=[f't{t}' for t in range(T)]).to_csv(
        os.path.join(out, 'static_leiden_groups.csv'), index_label='node')

    # time steps whose ground truth has a single group carry no community
    # structure (NMI is 0 by construction): they are excluded from scoring
    valid = np.array([len(np.unique(x)) > 1 for x in truth])
    n_true = len(np.unique(truth[valid]))
    rows, series = [], {}
    nmi_s, ari_s, gnmi_s = score(static, truth, valid, global_labels=False)
    series['static'] = nmi_s
    rows.append(dict(method='static (Leiden)', history=np.nan,
                     n_labels=np.nan, n_true=n_true, n_valid_steps=valid.sum(),
                     mean_step_NMI=np.nanmean(nmi_s), mean_step_ARI=np.nanmean(ari_s),
                     global_NMI=gnmi_s, changes_within=np.nan, changes_boundary=np.nan))
    tw, tb = label_changes(truth, valid)

    dcs = {}
    for h in HISTORIES:
        dc = run_majortrack(static, n, h)
        dcs[h] = dc
        nmi, ari, gnmi = score(dc, truth, valid)
        series[f'DC h={h}'] = nmi
        cw, cb = label_changes(dc, valid)
        rows.append(dict(method='MajorTrack', history=h, n_labels=len(np.unique(dc[valid])),
                         n_true=n_true, n_valid_steps=valid.sum(),
                         mean_step_NMI=np.nanmean(nmi), mean_step_ARI=np.nanmean(ari),
                         global_NMI=gnmi,
                         changes_within=cw, changes_boundary=cb))
        pd.DataFrame(dc.T, columns=[f't{t}' for t in range(T)]).to_csv(
            os.path.join(out, f'dc_membership_history-{h}.csv'), index_label='node')
    rows.append(dict(method='ground truth', history=np.nan, n_labels=n_true,
                     n_true=n_true, n_valid_steps=valid.sum(), mean_step_NMI=1, mean_step_ARI=1,
                     global_NMI=1, changes_within=tw, changes_boundary=tb))
    metrics = pd.DataFrame(rows)
    metrics.insert(0, 'scenario', label)
    metrics.to_csv(os.path.join(out, 'metrics.csv'), index=False)
    pd.DataFrame(series).to_csv(os.path.join(out, 'per_step_NMI.csv'), index_label='t')

    # --- figure: membership heatmaps + per-step NMI
    order = np.lexsort((truth[-1], truth[0]))
    fig, axes = plt.subplots(1, 4, figsize=(17, 4.2),
                             gridspec_kw=dict(width_ratios=[1, 1, 1, 1.15]))
    membership_heatmap(axes[0], truth, order, 'ground truth')
    membership_heatmap(axes[1], dcs[1], order, 'MajorTrack h=1')
    membership_heatmap(axes[2], dcs[HISTORY_PLOT], order, f'MajorTrack h={HISTORY_PLOT}')
    axes[0].set_ylabel('element (sorted by truth at t=0, t=T)')
    for ax in axes[1:3]:
        ax.set_yticks([])
    ax = axes[3]
    ax.plot(series['static'], color='k', lw=1.2, label='static Leiden')
    cols = plt.get_cmap('viridis', len(HISTORIES))
    for k, h in enumerate(HISTORIES):
        ax.plot(series[f'DC h={h}'], color=cols(k), lw=0.9, label=f'DC h={h}')
    for b in range(STEPS_PER_MATRIX, T, STEPS_PER_MATRIX):
        ax.axvline(b - 0.5, color='grey', lw=0.4, ls=':')
    ax.set_ylim(0, 1.02)
    ax.set_xlabel('time step')
    ax.set_ylabel('NMI with ground truth')
    ax.legend(fontsize=7, ncol=2, loc='lower left')
    fig.suptitle(label, fontsize=10)
    fig.tight_layout()
    fig.savefig(os.path.join(out, f'majortrack_{label}.pdf'))
    plt.close(fig)
    return metrics


def summary_figure(df, path):
    df = df[df.method == 'MajorTrack'].copy()
    df['problem'] = df.scenario.str.extract(r'problem_([a-z-]+)_N')
    df['p_in'] = df.scenario.str.extract(r'pin-([0-9.]+)').astype(float)
    problems = ['merge', 'merge-split', 'merge-split-drift']
    metrics = [('mean_step_NMI', 'mean per-step NMI'), ('global_NMI', 'global NMI (node x time)'),
               ('n_labels', 'number of DCs'), ('changes_within', 'spurious DC changes / step')]
    fig, axes = plt.subplots(len(metrics), 3, figsize=(11, 10), sharex=True)
    colors = {0.2: '#d95f02', 0.5: '#7570b3', 0.8: '#1b9e77'}
    for j, prob in enumerate(problems):
        for i, (m, lab) in enumerate(metrics):
            ax = axes[i, j]
            for p, sub in df[df.problem == prob].groupby('p_in'):
                ax.plot(sub.history, sub[m], 'o-', color=colors[p], label=f'$p_{{in}}$={p}')
            if m == 'n_labels' and (df.problem == prob).any():
                ax.axhline(df[df.problem == prob].n_true.iloc[0], color='k', ls='--', lw=0.8,
                           label='true')
            ax.set_xscale('log')
            if j == 0:
                ax.set_ylabel(lab)
            if i == 0:
                ax.set_title(prob)
            if i == len(metrics) - 1:
                ax.set_xlabel('history parameter')
    axes[0, 0].legend(fontsize=8)
    axes[2, 0].legend(fontsize=8)
    fig.tight_layout()
    fig.savefig(path)
    plt.close(fig)


if __name__ == '__main__':
    # optional arguments: substrings selecting the scenarios to (re)analyse;
    # the summary is rebuilt from the metrics.csv of every analysed scenario
    folders = sorted(f for f in glob.glob(os.path.join(DIR_DATA, 'problem_*'))
                     if os.path.isdir(f))
    selected = sys.argv[1:]
    for f in folders:
        if selected and not any(s in os.path.basename(f) for s in selected):
            continue
        print('analysing', os.path.basename(f), flush=True)
        analyse(f)
    done = [os.path.join(f, 'majortrack_results', 'metrics.csv') for f in folders]
    df = pd.concat([pd.read_csv(p) for p in done if os.path.exists(p)], ignore_index=True)
    df.to_csv(os.path.join(DIR_DATA, 'majortrack_summary.csv'), index=False)
    summary_figure(df, os.path.join(DIR_DATA, 'majortrack_summary.pdf'))
    pd.set_option('display.width', 200)
    print(df.round(3).to_string())
